{
  "missing_information": [
    {
      "category": "Transfer Trigger",
      "gap": "The condition or event that initiates a sample transfer is not defined (e.g., scheduled evaluation, ad-hoc request, upstream process output).",
      "why_it_matters": "Without knowing what triggers the transfer, it is impossible to determine whether the initiation step can be automated or requires manual intervention."
    },
    {
      "category": "Evaluation Criteria",
      "gap": "There is no description of what the evaluation process entails or what criteria determine whether a sample is 'unnecessary' after evaluation.",
      "why_it_matters": "The decision logic for flagging samples for disposal must be explicit to model the branching condition and assess rule-based automation feasibility."
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "The actors involved at each step (who initiates transfer, who performs evaluation, who approves disposal) are not identified.",
      "why_it_matters": "Role clarity is required to map handoffs, identify bottlenecks, and determine which steps need human authorization versus system execution."
    },
    {
      "category": "Disposal Request Process",
      "gap": "The steps, approvals, and systems involved in the disposal request process are not described.",
      "why_it_matters": "The disposal subprocess may involve compliance, safety, or regulatory requirements that add mandatory steps and affect automation scope."
    },
    {
      "category": "System Integration",
      "gap": "It is unclear which information systems (e.g., inventory, laboratory management, request tracking) are used to record or manage transfers and disposal requests.",
      "why_it_matters": "System touchpoints determine data availability for process mining and identify integration points for automation."
    },
    {
      "category": "Timing and SLAs",
      "gap": "There are no defined timeframes or service-level expectations for completing transfers, evaluations, or disposal requests.",
      "why_it_matters": "Timing constraints are essential for identifying delays, measuring cycle time, and prioritizing automation efforts."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What specific event or condition triggers a wafer sample to be transferred for evaluation — for example, is it a scheduled batch cycle, a downstream team's request, or an automated signal from a preceding process step?",
      "targets": ["Transfer Trigger"]
    },
    {
      "id": "Q2",
      "question": "What criteria or outcomes from the evaluation determine that a sample is classified as 'unnecessary' and therefore eligible for disposal?",
      "targets": ["Evaluation Criteria"]
    },
    {
      "id": "Q3",
      "question": "Which roles or teams are responsible for each major step — initiating the transfer, performing the evaluation, submitting the disposal request, and approving it?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q4",
      "question": "What are the specific steps in the disposal request process, and are there any approval stages, compliance checks, or regulatory requirements that must be completed before disposal is carried out?",
      "targets": ["Disposal Request Process"]
    },
    {
      "id": "Q5",
      "question": "Which information systems are used to log, track, or manage sample transfers and disposal requests throughout this workflow?",
      "targets": ["System Integration"]
    },
    {
      "id": "Q6",
      "question": "Are there defined time limits or service-level expectations for how quickly a transfer must be completed after it is requested, or for how long a disposal request should take from submission to completion?",
      "targets": ["Timing and SLAs"]
    }
  ]
}
